using System.Text.Json;
namespace DockForge;
public sealed class ItemEditor : Window {
 public ItemEditor(Item original,bool child=false){var item=JsonSerializer.Deserialize<Item>(JsonSerializer.Serialize(original,Settings.Json),Settings.Json)!;Title="Edit "+(item.IsGroup?"group":"item");Width=Math.Min(900,SystemParameters.WorkArea.Width-32);Height=Math.Min(850,SystemParameters.WorkArea.Height-32);MinWidth=400;MinHeight=400;WindowStartupLocation=WindowStartupLocation.CenterOwner;
  var root=new DockPanel{Margin=new Thickness(20)};var footer=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};footer.Children.Add(Ui.Action("Cancel",()=>Close()));footer.Children.Add(Ui.Action("Save item",()=>{if(string.IsNullOrWhiteSpace(item.Name)){MessageBox.Show("Enter a name.");return;}if(item.Kind==ItemKind.Website&&(!Uri.TryCreate(item.Target,UriKind.Absolute,out var uri)||uri.Scheme is not("http" or "https"))){MessageBox.Show("Enter an http or https address.");return;}foreach(var property in typeof(Item).GetProperties().Where(p=>p.CanWrite))property.SetValue(original,property.GetValue(item));DialogResult=true;}));DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);var form=new ResponsiveForm();root.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});Content=root;
  form.Children.Add(Ui.Text(item.IsGroup?"Group details":"Item details",24,true));Ui.Input(form,"Name",item.Name,v=>item.Name=v);
  if(item.Kind is ItemKind.Shortcut or ItemKind.Website or ItemKind.LinkedFolder){var target=Ui.Input(form,item.Kind==ItemKind.Website?"Website address":"Target",item.Target,v=>item.Target=v);if(item.Kind!=ItemKind.Website){var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(Ui.Action("Choose file",()=>{var path=Ui.File();if(path!=null){target.Text=path;item.AppId="";}}));row.Children.Add(Ui.Action("Choose folder",()=>{var path=Ui.Folder();if(path!=null)target.Text=path;}));form.Children.Add(row);}}
  if(item.Kind is not(ItemKind.Spacer or ItemKind.Separator)){var icon=Ui.Input(form,"Custom icon (optional)",item.Icon,v=>item.Icon=v);form.Children.Add(Ui.Action("Choose icon",()=>{var path=Ui.File(true);if(path!=null)icon.Text=path;}));}
  if(item.Kind==ItemKind.Shortcut){Ui.Input(form,"Launch arguments",item.Arguments,v=>item.Arguments=v);Ui.Input(form,"Working folder",item.WorkingDirectory,v=>item.WorkingDirectory=v);if(item.AppId.Length>0)form.Children.Add(Ui.Text("Installed app: "+item.AppId,12));}
  if(item.Kind==ItemKind.Spacer)Ui.Number(form,"Spacer size",item.SpacerSize,4,400,v=>item.SpacerSize=v);
  if(item.IsGroup){Ui.Choice(form,"Popup layout",item.Layout,v=>item.Layout=v);Ui.Choice(form,"Sort",item.Sort,v=>item.Sort=v);Ui.Check(form,"Descending order",item.Descending,v=>item.Descending=v);Ui.Number(form,"Popup width",item.PopupWidth,200,1000,v=>item.PopupWidth=v);Ui.Number(form,"Popup height",item.PopupHeight,150,1000,v=>item.PopupHeight=v);Ui.Number(form,"Item icon size",item.GroupIconSize,16,96,v=>item.GroupIconSize=v);Ui.Check(form,"Show item labels",item.GroupShowLabels,v=>item.GroupShowLabels=v);Ui.Check(form,"Hide shortcut badges",item.HideShortcutBadges,v=>item.HideShortcutBadges=v);Ui.Check(form,"Open on hover",item.OpenOnHover,v=>item.OpenOnHover=v);Ui.Number(form,"Hover delay (milliseconds)",item.HoverDelay,100,5000,v=>item.HoverDelay=(int)v);Ui.Check(form,"Keep open after launching",item.KeepOpen,v=>item.KeepOpen=v);
   if(item.Kind==ItemKind.LinkedFolder){Ui.Choice(form,"Folder contents",item.Filter,v=>item.Filter=v);Ui.Input(form,"Extensions separated by semicolons",item.Extensions,v=>item.Extensions=v);}
   else{Ui.Label(form,"Group items");var list=new ListBox{Height=150,DisplayMemberPath="Name"};void Refresh(){list.ItemsSource=null;list.ItemsSource=item.Children;}Refresh();form.Children.Add(list);var row=new WrapPanel();row.Children.Add(Ui.Action("Add app",()=>{var p=new AppPicker{Owner=this};if(p.ShowDialog()==true){item.Children.AddRange(p.Selected);Refresh();}}));row.Children.Add(Ui.Action("Add file",()=>{var path=Ui.File();if(path!=null){item.Children.Add(Item.FromPath(path));Refresh();}}));row.Children.Add(Ui.Action("Add folder",()=>{var path=Ui.Folder();if(path!=null){item.Children.Add(Item.FromPath(path));Refresh();}}));row.Children.Add(Ui.Action("Add website",()=>{var i=new Item{Kind=ItemKind.Website};if(new ItemEditor(i,true){Owner=this}.ShowDialog()==true){item.Children.Add(i);Refresh();}}));row.Children.Add(Ui.Action("Edit",()=>{if(list.SelectedItem is Item i&&new ItemEditor(i,true){Owner=this}.ShowDialog()==true)Refresh();}));row.Children.Add(Ui.Action("Remove",()=>{if(list.SelectedItem is Item i){item.Children.Remove(i);Refresh();}}));form.Children.Add(row);}
  }
 }
}
public sealed class AppPicker : Window {
 public List<Item> Selected{get;private set;}=[];
 public AppPicker(){Title="Add installed apps";Width=530;Height=650;WindowStartupLocation=WindowStartupLocation.CenterOwner;var root=new DockPanel{Margin=new Thickness(22)};var heading=Ui.Text("Choose your apps",24,true);DockPanel.SetDock(heading,Dock.Top);root.Children.Add(heading);var footer=new StackPanel{Orientation=Orientation.Horizontal};var list=new ListBox{DisplayMemberPath="Name",SelectionMode=SelectionMode.Extended};footer.Children.Add(Ui.Action("Add selected apps",()=>{Selected=list.SelectedItems.Cast<Item>().Select(BarWindow.CloneItem).ToList();DialogResult=true;}));footer.Children.Add(Ui.Action("Cancel",()=>Close()));DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);root.Children.Add(list);Content=root;Loaded+=(_,_)=>list.ItemsSource=ShellService.InstalledApps();}
}
